/**
 * Generate CSS font fallback overrides (size-adjust + overrides) based on actual font files.
 *
 * @author
 * - Put this file in: /assets/js/vendor/font-metrics.js
 *
 * Usage:
 *   node assets/js/vendor/font-metrics.js \
 *     --target assets/lib/font/mafont/Roboto-Regular.ttf \
 *     --fallback assets/lib/font/mafont/Arial.ttf \
 *     --family roboto-fallback \
 *     --out assets/styles/_font-fallbacks.generated.scss
 */

const fs = require("fs");
const path = require("path");
const fontkit = require("fontkit");

/**
 * Parse CLI arguments.
 * @returns {{ target: string, fallback: string, family: string, out: string }}
 */
function parseArgs() {
    const args = process.argv.slice(2);
    const get = (name, def = null) => {
        const i = args.indexOf(name);
        if (i === -1) return def;
        return args[i + 1] ?? def;
    };

    const target = get("--target");
    const fallback = get("--fallback");
    const family = get("--family", "font-fallback");
    const out = get("--out", null);

    if (!target || !fallback || !out) {
        throw new Error(
            "Missing args. Required: --target <file> --fallback <file> --out <file> [--family <name>]"
        );
    }

    return { target, fallback, family, out };
}

/**
 * Read font metrics. Prefer OS/2 typo metrics when available.
 * @param {string} filePath
 * @returns {{ upm: number, xHeight: number, ascent: number, descent: number, lineGap: number }}
 */
function readMetrics(filePath) {
    const buf = fs.readFileSync(filePath);
    const font = fontkit.create(buf);

    const upm = font.unitsPerEm;
    const os2 = font["OS/2"] || {};

    const xHeight = os2.sxHeight || font.xHeight || 0;
    const ascent = os2.sTypoAscender ?? font.ascent;
    const descentAbs = Math.abs(os2.sTypoDescender ?? font.descent);
    const lineGap = os2.sTypoLineGap ?? font.lineGap ?? 0;

    return { upm, xHeight, ascent, descent: descentAbs, lineGap };
}

/**
 * Convert a font unit value to a percentage of em.
 * @param {number} value
 * @param {number} upm
 * @returns {number}
 */
function toPercentOfEm(value, upm) {
    return (value / upm) * 100;
}

/**
 * Compute size-adjust using x-height matching.
 * @param {{ upm:number, xHeight:number }} target
 * @param {{ upm:number, xHeight:number }} fallback
 * @returns {number}
 */
function computeSizeAdjust(target, fallback) {
    const targetX = target.xHeight / target.upm;
    const fallbackX = fallback.xHeight / fallback.upm;

    if (!targetX || !fallbackX) {
        throw new Error(
            "Missing x-height on one of the fonts (OS/2.sxHeight or font.xHeight)."
        );
    }

    return (targetX / fallbackX) * 100;
}

/**
 * Format number with stable precision.
 * @param {number} n
 * @returns {string}
 */
function fmt(n) {
    return Number(n).toFixed(8).replace(/\.?0+$/, "");
}

(function main() {
    const { target, fallback, family, out } = parseArgs();

    const targetAbs = path.resolve(process.cwd(), target);
    const fallbackAbs = path.resolve(process.cwd(), fallback);
    const outAbs = path.resolve(process.cwd(), out);

    if (!fs.existsSync(targetAbs)) throw new Error(`Target font not found: ${targetAbs}`);
    if (!fs.existsSync(fallbackAbs)) throw new Error(`Fallback font not found: ${fallbackAbs}`);

    const targetM = readMetrics(targetAbs);
    const fallbackM = readMetrics(fallbackAbs);

    const sizeAdjust = computeSizeAdjust(targetM, fallbackM);
    const ascentOverride = toPercentOfEm(targetM.ascent, targetM.upm);
    const descentOverride = toPercentOfEm(targetM.descent, targetM.upm);
    const lineGapOverride = toPercentOfEm(targetM.lineGap, targetM.upm);

    const fallbackFileName = path.basename(fallbackAbs).replace(/\\/g, "/");

    const scss = `// AUTO-GENERATED FILE. DO NOT EDIT.
// Generated by assets/js/vendor/font-metrics.js

@if not $enable-medias-queries {
  @font-face {
    font-family: ${family};
    src: url("../../../lib/fonts/Arial/${fallbackFileName}") format("truetype");
    size-adjust: ${fmt(sizeAdjust)}%;
    ascent-override: ${fmt(ascentOverride)}%;
    descent-override: ${fmt(descentOverride)}%;
    line-gap-override: ${fmt(lineGapOverride)}%;
    font-display: swap;
  }
}
`;

    fs.mkdirSync(path.dirname(outAbs), { recursive: true });
    fs.writeFileSync(outAbs, scss, "utf8");

    // eslint-disable-next-line no-console
    console.log(`Generated: ${outAbs}`);
})();